//! Conformance test: Pasture's in-tree `ErrorCurve` (ADR-124, IMP-13) against
//! the UCCI golden vectors (issue #4).
//!
//! The vectors in `tests/golden/calibration.json` are copied **verbatim** from
//! the UCCI reference repository (Varun Kotte, MIT —
//! <https://github.com/varunkotte6/ucci>, `tests/golden/calibration.json`,
//! schema `ucci-golden/1`, generated by the Python reference package with
//! `tools/make_golden.py`). They pin the weighted-PAV isotonic calibrator of
//! UCCI paper Section 4.2 to an absolute tolerance of 1e-12.
//!
//! The bridge between the two APIs is the one proposed in issue #4: negating
//! the mean logprob maps Pasture's non-increasing curve onto the
//! non-decreasing fit the vectors use. Concretely, a golden sample
//! `(u, e)` (uncertainty, error indicator) becomes a Pasture label
//! `LabeledLogprob { logprob: -u, correct: e == 0 }`, and the fitted value at
//! `u` is read back as `curve.error_at(-u)`.
//!
//! Scope — what is asserted, and what is deliberately not:
//!
//! - `pav` cases with binary, unweighted targets: the fitted value at every
//!   point must match. (ErrorCurve fits 0/1 error indicators only, so the
//!   general real-valued `pav` cases do not map onto it.)
//! - `calibrator_fit` cases without sample weights and with binary labels:
//!   every fitted knot value, the sample count, and predictions at knots and
//!   outside the fitted range (where both implementations clip to the end
//!   knots) must match.
//! - `fit_error_empty` / `pav_error_empty`: fitting no labels yields `None`.
//!
//! Skipped by design (counted and printed, never silently):
//!
//! - Weighted cases: `ErrorCurve` is unweighted.
//! - Soft (non-binary) labels: `ErrorCurve` takes correctness booleans.
//! - `calibrator_from_knots` / `calibrator_predict` cases: Pasture has no
//!   from-knots constructor.
//! - Predictions strictly between knots: UCCI interpolates linearly between
//!   knots, while `ErrorCurve` is deliberately a step function (see
//!   `src/calibrate.rs`). Conformance is asserted where the two semantics
//!   coincide, not where they differ by design.
//! - The remaining error cases: where UCCI raises a typed error for invalid
//!   input, Pasture validates by dropping non-finite labels and returning
//!   `None` — a documented difference in failure style, not in fitted values.
//!
//! Known divergence (found by this test, 2026-11-11): the reference pools
//! tied `u` values (count-weighted) before running PAV, so every observation
//! at the same `u` shares one fitted value. `ErrorCurve` fits individual
//! points, so at a tied logprob its step lookup returns the last block rather
//! than the tie-pooled mean (e.g. `u = [0.3, 0.3, 0.3]`, `e = [1, 0, 0]`:
//! reference 1/3, ErrorCurve 0). Every case without tied `u` matches to
//! 1e-12; the tie-bearing cases (`fit_ties`, `fit_rounded_ties_800`,
//! `fit_signed_zero`, `fit_single_value`) fail on exactly the tied knots.
//! Pooling equal logprobs in `ErrorCurve::fit` would close the gap; that is a
//! deliberate follow-up change to `src/calibrate.rs`, not part of the change
//! that introduces this test.

use pasture::calibrate::{ErrorCurve, LabeledLogprob};
use pasture::json::{parse, JsonValue};

fn num(v: &JsonValue) -> f64 {
    match v {
        JsonValue::Number(n) => *n,
        JsonValue::Str(s) if s == "nan" => f64::NAN,
        JsonValue::Str(s) if s == "inf" => f64::INFINITY,
        JsonValue::Str(s) if s == "-inf" => f64::NEG_INFINITY,
        other => panic!("not a number: {other:?}"),
    }
}

fn nums(v: &JsonValue) -> Vec<f64> {
    v.as_array()
        .expect("array of numbers")
        .iter()
        .map(num)
        .collect()
}

fn is_null_or_absent(v: Option<&JsonValue>) -> bool {
    matches!(v, None | Some(JsonValue::Null))
}

#[derive(Default)]
struct Stats {
    comparisons: usize,
    max_diff: f64,
    pav_run: usize,
    fit_run: usize,
    predict_checks: usize,
    skipped_weighted: usize,
    skipped_non_binary: usize,
    skipped_no_constructor: usize,
    skipped_error_style: usize,
    skipped_interpolation: usize,
    failures: Vec<String>,
}

impl Stats {
    fn compare(&mut self, path: &str, got: f64, want: f64, tol: f64) {
        self.comparisons += 1;
        let d = (got - want).abs();
        if d.is_finite() {
            self.max_diff = self.max_diff.max(d);
        }
        if d.is_nan() || d > tol {
            self.failures
                .push(format!("{path}: got {got:?}, want {want:?} (tol {tol:e})"));
        }
    }
}

fn labels(u: &[f64], e: &[f64]) -> Vec<LabeledLogprob> {
    u.iter()
        .zip(e)
        .map(|(&u, &e)| LabeledLogprob {
            logprob: -u,
            correct: e == 0.0,
        })
        .collect()
}

#[test]
fn error_curve_matches_ucci_golden_vectors() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/golden/calibration.json");
    let text = std::fs::read_to_string(path).expect("golden vectors file present");
    let doc = parse(&text).expect("golden vectors parse");
    assert_eq!(
        doc.get("schema").and_then(JsonValue::as_str),
        Some("ucci-golden/1"),
        "unknown golden schema"
    );
    let tol = num(doc.get("tolerance").expect("tolerance field"));
    let cases = doc
        .get("cases")
        .and_then(JsonValue::as_array)
        .expect("cases array");

    let mut st = Stats::default();
    for case in cases {
        let id = case.get("id").and_then(JsonValue::as_str).expect("case id");
        let func = case.get("fn").and_then(JsonValue::as_str).expect("case fn");
        let input = case.get("input").expect("case input");
        let expected = case.get("expected");
        let has_error = case.get("error").is_some();

        match func {
            "pav" => {
                if has_error {
                    if id == "pav_error_empty" {
                        assert!(
                            ErrorCurve::fit(&[]).is_none(),
                            "{id}: empty fit must be None"
                        );
                        st.pav_run += 1;
                    } else {
                        st.skipped_error_style += 1;
                    }
                    continue;
                }
                if !is_null_or_absent(input.get("w")) {
                    st.skipped_weighted += 1;
                    continue;
                }
                let y = nums(input.get("y").expect("pav y"));
                if y.iter().any(|&v| v != 0.0 && v != 1.0) {
                    st.skipped_non_binary += 1;
                    continue;
                }
                let want = nums(expected.expect("pav expected").get("fit").expect("fit"));
                let labeled: Vec<LabeledLogprob> = y
                    .iter()
                    .enumerate()
                    .map(|(i, &v)| LabeledLogprob {
                        logprob: -(i as f64),
                        correct: v == 0.0,
                    })
                    .collect();
                let Some(curve) = ErrorCurve::fit(&labeled) else {
                    st.failures.push(format!("{id}: fit returned None"));
                    continue;
                };
                st.pav_run += 1;
                for (i, &w) in want.iter().enumerate() {
                    st.compare(
                        &format!("{id}.fit[{i}]"),
                        curve.error_at(-(i as f64)),
                        w,
                        tol,
                    );
                }
            }
            "calibrator_fit" => {
                if has_error {
                    if id == "fit_error_empty" {
                        assert!(
                            ErrorCurve::fit(&[]).is_none(),
                            "{id}: empty fit must be None"
                        );
                        st.fit_run += 1;
                    } else {
                        st.skipped_error_style += 1;
                    }
                    continue;
                }
                if !is_null_or_absent(input.get("sample_weight")) {
                    st.skipped_weighted += 1;
                    continue;
                }
                let u = nums(input.get("u").expect("fit u"));
                let e = nums(input.get("e").expect("fit e"));
                if e.iter().any(|&v| v != 0.0 && v != 1.0) {
                    st.skipped_non_binary += 1;
                    continue;
                }
                let expected = expected.expect("fit expected");
                let Some(curve) = ErrorCurve::fit(&labels(&u, &e)) else {
                    st.failures.push(format!("{id}: fit returned None"));
                    continue;
                };
                st.fit_run += 1;
                // Sample count.
                let n: usize = curve.breakpoints().iter().map(|b| b.2).sum();
                let want_n = num(expected.get("n_samples").expect("n_samples")) as usize;
                if n != want_n {
                    st.failures
                        .push(format!("{id}.n_samples: got {n}, want {want_n}"));
                }
                // Fitted knot values.
                let xs = nums(expected.get("x").expect("knot x"));
                let ys = nums(expected.get("y").expect("knot y"));
                for (k, (&x, &y)) in xs.iter().zip(&ys).enumerate() {
                    st.compare(&format!("{id}.knot[{k}]"), curve.error_at(-x), y, tol);
                }
                // Predictions where step and interpolation semantics coincide:
                // at knots, and outside the fitted range (both clip).
                let query = nums(input.get("query").expect("query"));
                let pred = nums(expected.get("predict").expect("predict"));
                let (lo, hi) = (xs[0], xs[xs.len() - 1]);
                for (i, (&q, &p)) in query.iter().zip(&pred).enumerate() {
                    if q <= lo || q >= hi || xs.contains(&q) {
                        st.predict_checks += 1;
                        st.compare(&format!("{id}.predict[{i}]"), curve.error_at(-q), p, tol);
                    } else {
                        st.skipped_interpolation += 1;
                    }
                }
            }
            "calibrator_from_knots" | "calibrator_predict" => {
                st.skipped_no_constructor += 1;
            }
            other => panic!("unknown golden function {other:?}"),
        }
    }

    eprintln!(
        "ucci conformance: pav {} cases, fit {} cases, {} value comparisons \
         ({} at knots/out-of-range predictions), max abs diff {:e}; skipped: \
         {} weighted, {} non-binary, {} no-constructor, {} error-style, \
         {} interpolation points",
        st.pav_run,
        st.fit_run,
        st.comparisons,
        st.predict_checks,
        st.max_diff,
        st.skipped_weighted,
        st.skipped_non_binary,
        st.skipped_no_constructor,
        st.skipped_error_style,
        st.skipped_interpolation
    );
    assert!(
        st.failures.is_empty(),
        "{} golden mismatches:\n{}",
        st.failures.len(),
        st.failures
            .iter()
            .map(|s| s.as_str())
            .collect::<Vec<_>>()
            .join("\n")
    );
    // Coverage floors: the test must not silently pass on an empty subset.
    assert!(st.pav_run >= 1, "no pav case ran");
    assert!(st.fit_run >= 12, "too few fit cases ran: {}", st.fit_run);
    assert!(
        st.comparisons >= 500,
        "too few values compared: {}",
        st.comparisons
    );
}
